DROP TABLE IF EXISTS `cad_forn`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `cad_forn` (
  `CODIGO` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `RAZAO_SOCIAL` varchar(100) NOT NULL DEFAULT '',
  `NOME_FANTASIA` varchar(100) NOT NULL DEFAULT '',
  `FIS_JUR` enum('F','J') NOT NULL DEFAULT 'J' COMMENT 'F = Pessoa FÃ­sica; J = Pessoa JurÃ­dica',
  `REGIME_TRIBUT` enum('S','SE','N') NOT NULL DEFAULT 'N' COMMENT 'S = Simples Nacional; SE = Simples Nacional (excesso de sublimite de receita bruta); N = Normal',
  `ATIV_EMPR` enum('D','I','O','M','E','F','P','R','U') NOT NULL DEFAULT 'U' COMMENT 'D = Distribuidora; I = IndÃºstria; O = O.N.G.; M = Ã“rgÃ£o Municipal; E = Ã“rgÃ£o Estadual; F = Ã“rgÃ£o Federal; P = Prestadora de ServiÃ§os; R = Revendedora; U = (Outro)',
  `PARA_CONSUMO` enum('N','S') NOT NULL DEFAULT 'N' COMMENT 'N = NÃ£o; S = Sim',
  `ENDERECO` varchar(100) NOT NULL DEFAULT '',
  `NUMERO` varchar(10) DEFAULT NULL,
  `COMPLEMENTO` varchar(100) DEFAULT NULL,
  `BAIRRO` varchar(100) DEFAULT NULL,
  `CIDADE` varchar(50) DEFAULT NULL,
  `ESTADO` char(2) DEFAULT NULL,
  `PAIS` char(4) NOT NULL DEFAULT '1058' COMMENT '0000',
  `CEP` char(9) DEFAULT '00000-000',
  `TELEFONE` varchar(15) NOT NULL DEFAULT '',
  `FAX` varchar(15) NOT NULL DEFAULT '',
  `TOLL_FREE` varchar(15) NOT NULL DEFAULT '',
  `EMAIL` varchar(50) DEFAULT NULL,
  `DATA_CADASTRO` date DEFAULT NULL,
  `OBSERVACOES` varchar(255) DEFAULT NULL,
  `OBSERVACOES2` varchar(255) DEFAULT NULL,
  `CNPJ` varchar(20) DEFAULT NULL,
  `CONTRIB` enum('N','S') NOT NULL DEFAULT 'S' COMMENT 'N = NÃ£o; S = Sim',
  `INSCRICAO` varchar(20) DEFAULT NULL,
  `SUFRAMA` char(9) NOT NULL DEFAULT '',
  `ATIVIDADE` int(10) unsigned DEFAULT 0,
  `CREDITO` float(10,2) DEFAULT 0.00,
  `CENTRO_CUSTO` int(10) unsigned DEFAULT NULL,
  `ATIVO` enum('N','S') DEFAULT 'S',
  `BANCO` char(5) NOT NULL DEFAULT '000-0',
  `AGENCIA` varchar(10) NOT NULL DEFAULT '',
  `COD_CONTA` bigint(20) NOT NULL DEFAULT 0,
  `CONTA` varchar(20) NOT NULL DEFAULT '',
  `DATA_ULT_CONTATO` date DEFAULT NULL COMMENT 'Data do ultimo registro de contato',
  `DATA_PROX_CONTATO` date DEFAULT NULL COMMENT 'Data do proximo registro de contato',
  `CMC` varchar(15) NOT NULL DEFAULT '' COMMENT 'InscriÃ§Ã£o Municipal',
  `DATA_RECAD` datetime DEFAULT NULL,
  `ENVIA_OBS1` varchar(255) DEFAULT NULL,
  `ENVIA_OBS2` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`CODIGO`) USING BTREE,
  KEY `RAZAO_SOCIAL` (`RAZAO_SOCIAL`) USING BTREE,
  KEY `NOME_FANTASIA` (`NOME_FANTASIA`) USING BTREE,
  KEY `CNPJ` (`CNPJ`) USING BTREE,
  KEY `LOCALIDADE` (`ESTADO`,`CIDADE`) USING BTREE
) ENGINE=MyISAM AUTO_INCREMENT=186 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci ROW_FORMAT=DYNAMIC COMMENT='Fornecedores';
